using namespace std;

string string_to_md5(string text) {
    // If 'text' is an empty string, return an empty string or handle as None.
    // Note: In C++, returning a string equivalent to "None" usually means an empty string 
    // or a specific null indicator. Based on the prompt logic:
    if (text.empty()) {
        return ""; // Or return a specific string representing None if required
    }

    unsigned char digest[MD5_DIGEST_LENGTH];

    // MD5 computes the hash of the input data
    MD5((unsigned char*)text.c_str(), text.length(), digest);

    // Convert the byte array to a hexadecimal string
    stringstream ss;
    for(int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        // setfill('0') and setw(2) ensures that single digit hex values 
        // (like 0x05) are represented as "05" instead of "5"
        ss << hex << setw(2) << setfill('0') << (int)digest[i];
    }

    return ss.str();
}

// Test the function
