    string input = "Hello world";
    string hash = string_to_md5(input);
    printf("Input: %s\nMD5: %s\n", input.c_str(), hash.c_str());

    // Expected: 3e25960a79dbc69b674cd4ec67a72c62
    return 0;
}
```

